(function(root){
  'use strict';
  const A=root.Allocation,provider=root.CardProviders.simulated(A),$=s=>document.querySelector(s);
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const cash=n=>new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN',minimumFractionDigits:0,maximumFractionDigits:2}).format(n/100);
  const day=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
  const uid=()=>crypto.randomUUID(),key=()=>mode==='demo'?'kasuapay-smart-demo-v1':'kasuapay-smart-guest-v1';
  let mode='guest',state,storageError='',feedback='',pending=false,dialogKind='',route='smart';
  try{mode=localStorage.getItem('kasuapay-smart-mode')==='demo'?'demo':'guest';}catch{/* Guest remains usable when storage is unavailable. */}
  function initial(demo=false){let s=A.create();s.preparedRef='allowance-1';if(demo){s=A.subscription(s,{id:'demo-data',name:'Campus data',network:'Demo network',plan:'Demo 10 GB',amount:250000,limit:1000000,category:'Data',condition:'depleted',due:day()});s.partner={name:'Amara (demo)',relationship:'Older sibling',shareTotals:true,shareCategories:false,shareMilestones:true,shareAlerts:true,limit:8000000};}return s;}
  function load(){storageError='';try{const raw=localStorage.getItem(key());state=raw?A.validate(JSON.parse(raw)):initial(mode==='demo');}catch(error){state=initial(mode==='demo');storageError='Saved plan could not be read. Existing storage has not been overwritten. Use Reset demo for demo data, or restore browser access before saving.';}}
  function commit(next){A.validate(next);try{localStorage.setItem(key(),JSON.stringify(next));}catch{throw Error('Browser storage is unavailable. This action was not saved; enable storage and retry.');}state=next;storageError='';try{localStorage.setItem('kasuapay-smart-mode',mode);}catch{/* The plan was saved even if the workspace preference could not be saved. */}}
  function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
  const numeric=(label,name,kobo)=>field(label,name,(kobo/100).toFixed(2),'number','required min="0" max="1000000000" step="0.01"');
  function select(label,name,options,value){return `<label class="field">${label}<select name="${name}">${options.map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`;}
  function check(label,name,on){return `<label class="smart-check"><input type="checkbox" name="${name}" ${on?'checked':''}>${label}</label>`;}
  function btn(action,label,extra=''){return `<button type="button" class="button" data-smart="${action}" ${extra}>${label}</button>`;}
  function heading(title,subtitle,action=''){return `<div class="section-heading"><div><h2>${title}</h2><small>${subtitle}</small></div>${action}</div>`;}
  function history(list){return list.length?`<div class="smart-table-wrap"><table class="table"><thead><tr><th>REFERENCE / DATE</th><th>DETAILS</th><th>AMOUNT</th></tr></thead><tbody>${list.slice().reverse().map(e=>`<tr><td><code>${esc(e.ref)}</code><small>${esc(e.date)}</small></td><td>${esc(e.note)}<small>${e.kind==='income'?'Income received → automatically allocated':esc(e.category)+' · simulated spending'}</small></td><td>${e.kind==='income'?'+':'−'}${cash(e.amount)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No activity yet. Review your rules and simulate an incoming allowance.</div>';}
  function subscriptions(){const l=A.ledger(state);return `<section class="card">${heading('Essential recurring expenses','Renewals only run when you explicitly simulate them.',btn('subscription','＋ Add subscription'))}${state.subscriptions.map(s=>`<article class="goal-item"><div class="section-heading"><div><h3>${esc(s.name)}</h3><small>${esc(s.network)} · ${esc(s.plan)}</small></div><span class="badge">${s.condition==='depleted'?'Manual depletion signal':s.due<=day()?'Due now':'Upcoming'}</span></div><p>${cash(s.amount)} per renewal · monthly maximum ${cash(s.limit)}</p><p class="hint">Funding: ${esc(s.category)} (${cash(l.balances[s.category])} available). Next date: ${esc(s.due)}.</p><div class="smart-actions">${btn('renew',s.condition==='depleted'?'Data finished — simulate renewal':'Simulate due renewal',`data-id="${esc(s.id)}"`)}${btn('subscription','Edit',`data-id="${esc(s.id)}"`)}</div></article>`).join('')||'<div class="empty">Add a subscription to track its next date, funding budget and monthly limit.</div>'}<p class="hint">No network monitoring, airtime purchase, bank debit or background payment occurs. Your manual signal triggers a simulation.</p></section>`;}
  function partner(){const p=state.partner,v=A.partnerView(state);return `<div class="dashboard-grid"><section class="card">${heading('Your accountability agreement','Permissions are opt-in and read-only.',btn('partner','Configure partner'))}<h3>${esc(p.name||'No partner nominated')}</h3><p>${esc(p.relationship||'Choose someone you trust')}</p><span class="badge">${esc(v.status)}</span><p class="hint">Local preview only. No invitation or notification is sent. Partners cannot transfer, withdraw, or edit your settings.</p><p>Alert threshold: ${cash(p.limit)}</p></section><section class="card">${heading('Partner’s permitted view','Only the information you selected appears below.')}<h3>${esc(v.name||'Partner preview')}</h3>${v.totals?`<p>Income: ${cash(v.totals.income)}<br>Spent: ${cash(v.totals.spent)}<br>Remaining: ${cash(v.totals.remaining)}</p>`:''}${v.categories?`<ul>${Object.entries(v.categories).map(([c,n])=>`<li>${c}: ${cash(n)}</li>`).join('')}</ul>`:''}${v.milestones?`<p>Savings milestone: ${cash(A.ledger(state).balances.Savings)} reserved.</p><p>${state.events.filter(e=>e.kind==='income').length} allowance allocation milestone(s).</p>`:''}${v.alerts?`<div class="insight">${v.alerts.map(esc).join('<br>')} Simulated notification only.</div>`:''}${!p.shareTotals&&!p.shareCategories&&!p.shareMilestones&&!p.shareAlerts?'<div class="empty">Nothing shared. Enable only the summaries you want your partner to see.</div>':''}</section></div>`;}
  function cards(){const c=provider.describe(state);return `<div class="dashboard-grid"><section class="card">${heading('BMoney card concept','SIMULATION — no issued card or verified provider connection.')}<div class="sim-card"><span>KasuaPay × BMoney concept</span><h3>DEMO CARD</h3><p>NO CARD NUMBER · NO CVV</p><strong>${cash(c.balance)}</strong><small>${esc(c.category)} budget available · ${esc(c.status)}</small></div><p class="hint">${esc(c.label)}. This experience represents a possible integration interface, not an existing BMoney capability.</p><div class="smart-actions">${btn('card-settings','Card settings')}${btn('freeze',c.status==='active'?'Freeze demo card':'Unfreeze demo card')}${btn('card-pay','Simulate purchase',c.status!=='active'?'disabled':'')}</div><p>Monthly card limit: ${cash(c.limit)}</p></section><section class="card">${heading('Card-linked activity','Every simulated purchase uses the linked category balance.')}${history(state.events.filter(e=>e.card))}</section></div>`;}
  function dashboard(){const l=A.ledger(state),processed=state.events.some(e=>e.ref===(state.preparedRef||'allowance-1'));return `<section class="card smart-plan">${heading('When money arrives, your plan takes over','1. Review rules → 2. Simulate income → 3. Explore your funded budgets.',btn('rules','Edit future allocation rules'))}<div class="smart-actions">${btn('scenario','Select ₦100,000 student demo')}${btn('allowance','Edit incoming amount / reference')}${btn('receive',processed?'Allowance processed ✓':'Simulate Incoming Allowance',processed?'disabled':'')}${processed?btn('next','Prepare next allowance'):''}</div><p class="hint">Incoming amount: <b>${cash(state.expected)}</b> · Reference: <code>${esc(state.preparedRef||'allowance-1')}</code>. Replaying this reference cannot credit your balance twice.</p></section><section class="summary-grid smart-summary"><article class="card balance-card"><div class="card-label">Total income received</div><div class="metric">${cash(l.income)}</div><div class="card-foot">${state.events.filter(e=>e.kind==='income').length} recorded incoming payment(s)</div></article><article class="card"><div class="card-label">Total actually spent</div><div class="metric">${cash(l.totalSpent)}</div><div class="card-foot">Allocated funds are not counted as expenses</div></article><article class="card safe-card"><div class="card-label">Remaining plan balance</div><div class="metric">${cash(l.remaining)}</div><div class="card-foot">Includes ${cash(l.reserved)} reserved savings / emergency<br>${cash(l.unallocated)} not allocated</div></article></section><section class="card">${heading('Your allocation rules and balances','Targets apply to each new income. Existing allocations retain their original rules.',btn('expense','Record simulated expense'))}<div class="smart-budget-grid">${state.rules.map(r=>{const allocated=l.allocated[r.category],spent=l.spent[r.category],left=l.balances[r.category];return `<article class="goal-item"><div class="row-label"><b>${esc(r.category)}</b><span class="badge">${r.essential?'Essential':r.category==='Savings'?'Reserved':'Flexible'}</span></div><div class="metric">${cash(left)}</div><p class="hint">Next target ${cash(r.target)}<br>Allocated ${cash(allocated)} · spent ${cash(spent)}</p><div class="track" role="progressbar" aria-label="${r.category} spent" aria-valuenow="${allocated?Math.round(spent/allocated*100):0}" aria-valuemin="0" aria-valuemax="100"><div class="fill" style="width:${allocated?spent/allocated*100:0}%"></div></div></article>`;}).join('')}</div><p class="hint">If income is smaller than the plan, essential categories receive funding first. A partially funded group is split proportionally to the nearest kobo. Extra income stays visibly unallocated. All totals cover this ongoing plan, not an automatic calendar reset.</p></section><div class="smart-stack">${subscriptions()}${partner()}</div><section class="card transactions-card">${heading('Recent transactions','Open the allocation ledger to inspect exact distribution records.','<a class="text-button" href="#ledger">Full ledger →</a>')}${history(state.events.slice(-5))}</section>`;}
  function ledgerPage(){return `<section class="card">${heading('Transaction and allocation history','Incoming payments, reserved allocations, actual expenses and failed attempts.')}${history(state.events)}${state.events.filter(e=>e.kind==='income').slice().reverse().map(e=>`<details class="goal-item"><summary>Allocation: ${esc(e.ref)} · ${cash(e.amount)}</summary><ul>${Object.entries(e.allocations).map(([c,n])=>`<li>${esc(c)}: ${cash(n)}</li>`).join('')}</ul><p class="hint">Unallocated on arrival: ${cash(e.amount-A.total(Object.values(e.allocations)))}. Rules were snapshotted when this income arrived.</p></details>`).join('')}<h3>Failed attempts</h3>${state.failures.length?state.failures.slice().reverse().map(f=>`<p class="smart-error"><code>${esc(f.ref)}</code> · ${esc(f.date)}<br>${esc(f.message)}</p>`).join(''):'<p class="hint">No failed attempts recorded.</p>'}</section>`;}
  function renderRoute(){const hash=location.hash.slice(1);if(!['smart','subscriptions','partner','cards','ledger'].includes(hash))return false;route=hash;const labels={smart:'Automated plan',subscriptions:'Subscriptions',partner:'Accountability',cards:'BMoney concept',ledger:'Allocation ledger'};document.querySelectorAll('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page==='smart');if(a.dataset.page==='smart')a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#page-label').textContent=labels[route];$('#greeting').textContent=labels[route];$('#subtitle').textContent='Your preferences first. Automatic allocation when income arrives.';$('#today').textContent=new Date().toLocaleDateString('en-NG',{day:'numeric',month:'long',year:'numeric'});$('#app').innerHTML=`<div class="smart-banner"><b>${mode==='demo'?'STUDENT DEMO':'GUEST PLAN'} · Simulated money only</b><span>No login · Browser-local · No real payments or sharing</span><div class="smart-actions">${btn('switch',mode==='demo'?'Return to guest plan':'Try demo mode')}${mode==='demo'?btn('reset','Reset demo'):''}</div></div>${storageError?`<p class="smart-error" role="alert">${esc(storageError)}</p>`:''}<div class="smart-feedback" role="status">${esc(feedback)}</div><nav class="smart-tabs" aria-label="Smart money sections">${Object.entries(labels).map(([k,v])=>`<a href="#${k}" ${k===route?'aria-current="page"':''}>${v}</a>`).join('')}</nav>${route==='smart'?dashboard():route==='subscriptions'?subscriptions():route==='partner'?partner():route==='cards'?cards():ledgerPage()}`;return true;}
  function ensureDialog(){if($('#smart-modal'))return;const el=document.createElement('dialog');el.id='smart-modal';el.innerHTML='<form id="smart-form"><div class="dialog-header"><h2 id="smart-title"></h2><button type="button" class="icon-button" data-smart="close" aria-label="Close">×</button></div><div id="smart-fields"></div><p id="smart-form-error" class="form-error" role="alert"></p><button id="smart-submit" type="submit" class="button primary full">Save / simulate</button></form>';document.body.appendChild(el);$('#smart-form').addEventListener('submit',submit);}
  function open(kind,id){ensureDialog();dialogKind=kind;$('#smart-form').dataset.id=id||'';$('#smart-form').dataset.ref=uid();let body='',title='';const opts=A.categories.filter(c=>c!=='Savings');if(kind==='rules'){title='Rules for future income';body=numeric('Expected income (₦)','expected',state.expected)+'<div class="allocation-fields">'+state.rules.map(r=>`<div>${numeric(r.category+' target (₦)',r.category,r.target)}${check('Essential priority',r.category+'Essential',r.essential)}</div>`).join('')+'</div><p class="hint">Targets cannot exceed expected income. Changes do not redistribute money already received.</p>';}
    if(kind==='allowance'){title='Configure incoming allowance';body=numeric('Incoming amount (₦)','expected',state.expected)+field('Unique payment reference','ref',state.preparedRef||'allowance-1','text','required maxlength="100"')+'<p class="hint">Saving this form does not credit money. Use Simulate Incoming Allowance after reviewing your rules.</p>';}
    if(kind==='expense'||kind==='card-pay'){title=kind==='expense'?'Simulate an expense':'Simulate card purchase';body=numeric('Amount (₦)','amount',0)+field('Description','note','','text','required maxlength="100"')+(kind==='expense'?select('Funding category','category',opts,'Food'):`<p class="hint">Linked to ${esc(state.card.category)}. No real card or merchant is charged.</p>`);}
    if(kind==='subscription'){const s=state.subscriptions.find(x=>x.id===id)||{name:'',network:'',plan:'',amount:250000,limit:1000000,category:'Data',condition:'depleted',due:day()};title='Recurring expense settings';body=field('Name','name',s.name,'text','required maxlength="100"')+field('Preferred network / provider','network',s.network,'text','required maxlength="100"')+field('Data plan / subscription','plan',s.plan,'text','required maxlength="100"')+numeric('Renewal amount (₦)','amount',s.amount)+numeric('Monthly maximum (₦)','limit',s.limit)+select('Funding category','category',opts,s.category)+select('Renewal condition','condition',['depleted','date'],s.condition)+field('Next renewal date','due',s.due,'date','required')+'<p class="hint">“depleted” requires your manual data-finished signal. “date” permits a simulation on or after the configured date. Nothing runs in the background.</p>';}
    if(kind==='renew'){const s=state.subscriptions.find(s=>s.id===id);title='Simulate subscription renewal';body=`<p>${esc(s.name)} · ${cash(s.amount)} from ${esc(s.category)}</p><p class="hint">No network purchase or actual debit occurs. Your current budget and monthly limit will be checked.</p>`+(s.condition==='depleted'?check('I indicate my data has finished','depleted',false):`<p class="hint">Due: ${esc(s.due)}. Simulation date: ${day()}.</p>`)+field('Unique renewal reference','ref',`${id}-${state.events.filter(e=>e.subscriptionId===id).length+1}`,'text','required maxlength="100"');}
    if(kind==='partner'){const p=state.partner;title='Accountability permissions';body=field('Partner name (simulated)','name',p.name,'text','required maxlength="100"')+field('Relationship','relationship',p.relationship,'text','required maxlength="100"')+numeric('Agreed spending alert threshold (₦)','limit',p.limit)+check('Share overall budget totals','shareTotals',p.shareTotals)+check('Share category balances','shareCategories',p.shareCategories)+check('Share saving / allowance milestones','shareMilestones',p.shareMilestones)+check('Share spending-limit alerts','shareAlerts',p.shareAlerts)+'<p class="hint">This is an on-screen permission preview. No contact details, invitation, access token or external notification are used.</p>';}
    if(kind==='card-settings'){title='Simulated card settings';body=select('Linked budget category','category',opts,state.card.category)+numeric('Monthly card spending limit (₦)','limit',state.card.limit)+'<p class="hint">The card shares the category balance. It does not create another wallet or additional funds.</p>';}
    if(kind==='reset'){title='Reset student demo?';body='<p>This clears simulated income, expenses and preferences in the demo only. Your guest and original manual records stay unchanged.</p>';}
    $('#smart-submit').textContent=kind==='reset'?'Reset demo now':'Save / simulate';
    $('#smart-title').textContent=title;$('#smart-fields').innerHTML=body;$('#smart-form-error').textContent='';$('#smart-modal').showModal();}
  function run(operation,ref,success){if(pending)return;pending=true;try{const result=operation();commit(result.state||result);feedback=result.duplicate?'This reference was already processed. No duplicate entry was created.':success;renderRoute();return true;}catch(error){feedback=error.message;if(ref){try{commit(A.failure(state,{ref},error));}catch{feedback+=' Browser storage also failed; the failed attempt could not be persisted.';}}renderRoute();return false;}finally{pending=false;}}
  function submit(e){e.preventDefault();const form=e.target,d=Object.fromEntries(new FormData(form)),ref=form.dataset.ref;let result;try{if(dialogKind==='reset'){mode='demo';result=initial(true);}if(dialogKind==='rules')result=A.rules(state,state.rules.map(r=>({category:r.category,target:A.parse(d[r.category]),essential:d[r.category+'Essential']==='on'})),A.parse(d.expected));
      if(dialogKind==='allowance'){const amount=A.positive(A.parse(d.expected));if(!d.ref.trim())throw Error('Provide a payment reference.');const prior=state.events.find(e=>e.ref===d.ref.trim());if(prior&&prior.amount!==amount)throw Error('This reference already belongs to a different payment.');result={...state,expected:amount,preparedRef:d.ref.trim()};}
      if(dialogKind==='expense'||dialogKind==='card-pay'){const input={ref,amount:A.positive(A.parse(d.amount)),note:d.note,date:day(),category:d.category};result=dialogKind==='expense'?A.spend(state,input):provider.purchase(state,input);}
      if(dialogKind==='subscription')result=A.subscription(state,{...d,id:form.dataset.id||uid(),amount:A.parse(d.amount),limit:A.parse(d.limit)});
      if(dialogKind==='renew')result=A.renew(state,{id:form.dataset.id,ref:d.ref,date:day(),depleted:d.depleted==='on'});
      if(dialogKind==='partner'){if(!d.name.trim()||!d.relationship.trim())throw Error('Add a partner name and relationship.');result={...state,partner:{name:d.name.trim(),relationship:d.relationship.trim(),limit:A.positive(A.parse(d.limit)),...Object.fromEntries(['shareTotals','shareCategories','shareMilestones','shareAlerts'].map(k=>[k,d[k]==='on']))}};}
      if(dialogKind==='card-settings')result={...state,card:{...state.card,category:d.category,limit:A.positive(A.parse(d.limit))}};
      commit(result.state||result);$('#smart-modal').close();feedback=result.duplicate?'Already processed. No duplicate transaction created.':dialogKind==='rules'?'Rules saved for the next incoming payment.':dialogKind==='renew'?'Simulated renewal successful. Budget and history updated.':'Saved successfully. All payments and sharing are simulated.';renderRoute();
    }catch(error){$('#smart-form-error').textContent=error.message;try{commit(A.failure(state,{ref:dialogKind==='renew'?d.ref:ref},error));}catch{/* Preserve visible error if storage is blocked. */}}}
  document.addEventListener('click',e=>{const button=e.target.closest('[data-smart]');if(!button)return;const action=button.dataset.smart;if(action==='close')return $('#smart-modal').close();if(action==='switch'){mode=mode==='demo'?'guest':'demo';try{localStorage.setItem('kasuapay-smart-mode',mode);}catch{}feedback='Switched workspace. Your other workspace is unchanged.';load();return renderRoute();}if(action==='scenario'||action==='reset'){if(state.events.length&&mode==='demo'){open('reset');return;}mode='demo';const ok=run(()=>initial(true),null,'₦100,000 scenario loaded. Review the rules, then simulate the incoming allowance.');if(ok){location.hash='smart';renderRoute();}return;}if(action==='next')return run(()=>({...state,preparedRef:uid()}),null,'Next allowance prepared. Edit its amount and review your rules before simulating it.');if(action==='receive'){const ref=state.preparedRef||'allowance-1';return run(()=>A.receive(state,{ref,amount:state.expected,date:day(),note:mode==='demo'?'Simulated monthly student allowance':'Simulated guest income'}),ref,'Income received and automatically allocated. Category balances are ready.');}if(action==='freeze')return run(()=>({...state,card:{...state.card,status:state.card.status==='active'?'frozen':'active'}}),null,'Simulated card status updated.');open(action,button.dataset.id);});
  load();root.SmartUI={renderRoute,openIncome:()=>open('allowance')};
})(window);
